SELECT COUNT(*) FROM posts as p, postLinks as pl, postHistory as ph, votes as v WHERE pl.PostId = p.Id AND v.PostId = p.Id AND ph.PostId = p.Id AND pl.CreationDate>=CAST('2011-11-21 22:39:41' AS TIMESTAMP) AND pl.CreationDate<=CAST('2014-09-01 16:29:56' AS TIMESTAMP) AND v.CreationDate>=CAST('2010-07-22 00:00:00' AS TIMESTAMP) AND v.CreationDate<=CAST('2014-09-14 00:00:00' AS TIMESTAMP)
